widget.solution:
import numpy as np

def return_correlation(x, y):
    """Correlation of the daily changes of x and y, to 4 places."""
    dx = np.diff(x)
    dy = np.diff(y)
    return round(float(np.corrcoef(dx, dy)[0, 1]), 4)


def drift_apart(x, y, beta):
    """np.std of y - beta * x over the first and the last quarter, to 4 places."""
    s = np.asarray(y) - beta * np.asarray(x)
    q = len(s) // 4
    first = np.std(s[:q])
    last = np.std(s[-q:])
    return round(float(first), 4), round(float(last), 4)
